CREATE TABLE `realtime_events` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NOT NULL,`recipient_id` CHAR(36) CHARACTER SET ascii NOT NULL,`notification_id` CHAR(36) CHARACTER SET ascii NOT NULL,`event_type` VARCHAR(80) CHARACTER SET ascii NOT NULL,`payload_json` JSON NOT NULL,`created_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),UNIQUE KEY `uq_realtime_notification`(`notification_id`),KEY `idx_realtime_replay`(`organization_id`,`workspace_id`,`recipient_id`,`id`),CONSTRAINT `fk_realtime_notification` FOREIGN KEY(`notification_id`) REFERENCES `notifications`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_realtime_recipient` FOREIGN KEY(`recipient_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
